import{_ as t,o,c as n,ae as a}from"./chunks/framework.YL6nI5ZP.js";const g=JSON.parse('{"title":"Build Your First Drainage Network and Run a Simulation","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/02-your-first-network.md","filePath":"tutorials/02-your-first-network.md"}'),r={name:"tutorials/02-your-first-network.md"};function s(i,e,l,d,c,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="build-your-first-drainage-network-and-run-a-simulation" tabindex="-1">Build Your First Drainage Network and Run a Simulation <a class="header-anchor" href="#build-your-first-drainage-network-and-run-a-simulation" aria-label="Permalink to &quot;Build Your First Drainage Network and Run a Simulation&quot;">​</a></h1><p>In this tutorial you will build a small stormwater network from scratch — nodes, links, and a subcatchment — set its parameters, run a simulation, and inspect the results, all through the app&#39;s user interface.</p><h2 id="what-you-ll-build" tabindex="-1">What you&#39;ll build <a class="header-anchor" href="#what-you-ll-build" aria-label="Permalink to &quot;What you&#39;ll build&quot;">​</a></h2><p>A small drainage network: a few nodes connected by conduits and ending in an outfall, plus a subcatchment that drains into the network. You&#39;ll use the drawing tools in the <strong>Left Tool Palette</strong>, set element properties in the right panel, and finish by running the simulation and reading its results.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Open the app: use the production site at <a href="https://swmm6.is-local.org" target="_blank" rel="noreferrer">https://swmm6.is-local.org</a>, or follow <a href="./../how-to/01-run-locally">How to Run the App Locally</a>. If this is your first time, work through <a href="./01-getting-started">Getting Started with Local SWMM</a> first.</p><h2 id="step-1-—-choose-your-units" tabindex="-1">Step 1 — Choose your units <a class="header-anchor" href="#step-1-—-choose-your-units" aria-label="Permalink to &quot;Step 1 — Choose your units&quot;">​</a></h2><ol><li>Click the <strong>Gear Icon</strong> on the map to open the <strong>Map Settings</strong> menu.</li><li>Under <strong>Units</strong>, select <strong>SI</strong> (meters, millimeters, LPS) or <strong>US</strong> (feet, inches, CFS).</li></ol><p>Note for later: if you add a 2D mesh to your model, <strong>2D is SI-only</strong> — a run with a 2D mesh present while units are US is rejected with a warning.</p><h2 id="step-2-—-add-nodes" tabindex="-1">Step 2 — Add nodes <a class="header-anchor" href="#step-2-—-add-nodes" aria-label="Permalink to &quot;Step 2 — Add nodes&quot;">​</a></h2><ol><li>In the <strong>Left Tool Palette</strong>, pick a <strong>Node tool</strong> — <strong>Junction</strong>, <strong>Outfall</strong>, <strong>Storage</strong>, or <strong>Divider</strong>.</li><li><strong>Click on the map</strong> to place a node of that type.</li></ol><p>Two things to notice:</p><ul><li>When you place a node, the application <strong>automatically extracts terrain elevation from Mapbox DEM</strong>. You can click <strong>Sample DEM Elevation</strong> in the <strong>Properties</strong> panel to update the elevation for a selected node.</li><li>Every element receives an auto-generated ID: nodes use the prefixes <code>J</code> (junction), <code>O</code> (outfall), <code>ST</code> (storage), <code>D</code> (divider), <code>RG</code> (rain gage); links use <code>C</code>, <code>P</code>, <code>W</code>, <code>OR</code>, <code>OL</code>; subcatchments use <code>S</code>.</li></ul><p>You must place at least <strong>one outfall</strong>: the app refuses to run a model with no nodes or no <code>OUTFALL</code>.</p><h2 id="step-3-—-connect-the-nodes-with-links" tabindex="-1">Step 3 — Connect the nodes with links <a class="header-anchor" href="#step-3-—-connect-the-nodes-with-links" aria-label="Permalink to &quot;Step 3 — Connect the nodes with links&quot;">​</a></h2><ol><li>In the <strong>Left Tool Palette</strong>, pick the <strong>Conduit</strong> tool (or <strong>Pump</strong>, <strong>Weir</strong>, or <strong>Orifice</strong> for other link types).</li><li><strong>Click a start node and an end node</strong> to draw the link.</li></ol><p>The conduit&#39;s length is computed automatically. New conduits come with sensible defaults: <code>roughness:0.013</code>, <code>autoLength:true</code>, <code>xShape:&#39;CIRCULAR&#39;</code>, <code>geom1:1.0</code>, <code>barrels:1</code>.</p><h2 id="step-4-—-add-a-subcatchment-and-a-rain-gage" tabindex="-1">Step 4 — Add a subcatchment and a rain gage <a class="header-anchor" href="#step-4-—-add-a-subcatchment-and-a-rain-gage" aria-label="Permalink to &quot;Step 4 — Add a subcatchment and a rain gage&quot;">​</a></h2><ol><li>Pick the <strong>Subcatchment</strong> tool, then <strong>click multiple points on the map</strong> to draw the subcatchment polygon. <strong>Double-click</strong> to close the polygon.</li><li>Pick the <strong>Rain Gage</strong> tool and <strong>click on the map</strong> to add a rain gage object.</li></ol><p>When you close a subcatchment, its area is computed automatically (in ha/ac) and the <strong>nearest hydraulic node is picked as its outlet</strong>.</p><p>Tip: with the <strong>Select Tool</strong> (<code>Esc</code>) you can click elements to select them and <strong>drag nodes to move their position</strong>. Undo with <code>Ctrl+Z</code>, redo with <code>Ctrl+Shift+Z</code>; <code>Del</code>/<code>Backspace</code> deletes the selected element.</p><h2 id="step-5-—-set-parameters" tabindex="-1">Step 5 — Set parameters <a class="header-anchor" href="#step-5-—-set-parameters" aria-label="Permalink to &quot;Step 5 — Set parameters&quot;">​</a></h2><ol><li>Click an element with the <strong>Select Tool</strong> to show its properties in the <strong>Properties</strong> tab of the right panel.</li><li>Edit the values you need.</li><li>For solver-wide settings, click <strong>Options</strong> on the <strong>Top Toolbar</strong>: <ul><li><strong>Node Continuity</strong>: select <strong>Legacy (Default)</strong> or <strong>SEMI_IMPLICIT (Enhanced)</strong> formulation.</li><li><strong>Anderson Acceleration</strong>: select <strong>Yes</strong> to accelerate Picard iteration convergence on stiff surcharge transitions.</li><li><strong>Physics-Based RDII Abstraction Recovery</strong>: enter recovery parameters (<code>k0</code>, <code>kT</code>, <code>Tref</code>) for rainfall infiltration recovery.</li></ul></li></ol><h2 id="step-6-—-save-your-work" tabindex="-1">Step 6 — Save your work <a class="header-anchor" href="#step-6-—-save-your-work" aria-label="Permalink to &quot;Step 6 — Save your work&quot;">​</a></h2><ul><li><strong>Save</strong>: click <strong>Save</strong> to export your model to a <code>.json</code> file (a pretty-printed <code>*.oswmm.json</code> project file) or save to browser storage.</li><li>The app also autosaves for you: every change is stored to browser storage after a short debounce (localStorage key <code>openswmm3d.project</code>, with an IndexedDB fallback), and restored on next load.</li><li><strong>Load / Import</strong> (from the <strong>Open Model ▾</strong> dropdown) lets you reopen project files, restore from browser storage, or import <code>.inp</code>, shapefile (<code>.zip</code>), and <code>.dxf</code> files.</li></ul><h2 id="step-7-—-run-the-simulation" tabindex="-1">Step 7 — Run the simulation <a class="header-anchor" href="#step-7-—-run-the-simulation" aria-label="Permalink to &quot;Step 7 — Run the simulation&quot;">​</a></h2><ol><li>Make sure your network contains <strong>at least one outfall node and connected conduits</strong>.</li><li>Click <strong>Run</strong> on the <strong>Top Toolbar</strong>.</li><li>Monitor progress in the <strong>Run Status</strong> window (progress percentage and simulated time in <code>Days</code> and <code>Hrs:Min</code>). You can <strong>Stop</strong> the simulation or <strong>Minimize</strong> it into a floating badge at any time.</li></ol><p>If the run aborts immediately with a warning, the causes are: no nodes, no <code>OUTFALL</code>, or <strong>US units with a 2D mesh</strong> (2D is SI-only).</p><h2 id="step-8-—-inspect-the-results" tabindex="-1">Step 8 — Inspect the results <a class="header-anchor" href="#step-8-—-inspect-the-results" aria-label="Permalink to &quot;Step 8 — Inspect the results&quot;">​</a></h2><ul><li><strong>Time Slider Panel</strong>: use the bottom animation bar to play, pause, change speed, or drag to a specific time step. The map colors update per step.</li><li><strong>Properties Tab</strong>: click any node or link to view its geometric properties and <strong>calculated flow values</strong>.</li><li><strong>Results Tab</strong>: select result categories to view summary tables — Node Depths, Node Inflows, Link Flows, and Subcatchment Runoff.</li><li><strong>Water Elevation Profile</strong>: select connected nodes and click <strong>Profile</strong> to view an interactive hydraulic profile plot.</li></ul><h2 id="what-you-should-see-at-the-end" tabindex="-1">What you should see at the end <a class="header-anchor" href="#what-you-should-see-at-the-end" aria-label="Permalink to &quot;What you should see at the end&quot;">​</a></h2><ul><li>A network with nodes (including an outfall), links, and a subcatchment, each with an ID and editable properties.</li><li>A completed run with populated <strong>Results</strong> and <strong>Report</strong> tabs in the right panel.</li><li>An animated playback of the simulation on the map via the time slider.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong>Add a 2D mesh</strong> for overland surface routing: use the <strong>Mesh2D</strong> button or the <strong>Data</strong> menu (<strong>2D Mesh</strong>) to open the mesh dialog, a 3-tab modal (<strong>Sources / Quality / Hydraulics</strong>) that generates the surface mesh. Remember 2D requires SI units.</li><li>Learn more about the model behind the UI in the reference sections of this documentation.</li></ul>',34)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
